"""pty-based runner: like probe.run but gives dog a real tty on stdout (and optionally stderr)."""
import sys, os, pty, select, subprocess, threading, time, errno
sys.path.insert(0,'/tmp/h')
import probe
from probe import nextport
from drive import serve_udp, serve_tcp

DOG = '/workspace/executable'

def _drain(fd, box):
    while True:
        try:
            r,_,_ = select.select([fd],[],[],0.2)
        except OSError:
            break
        if fd in r:
            try:
                d = os.read(fd, 65536)
            except OSError:
                break
            if not d: break
            box.append(d)
        else:
            if box.get_done if False else False: break
    return

def run_pty(dogargs, respbytes=None, tcp=False, patchid=True, env=None, count=1,
            timeout=15, out_tty=True, err_tty=True, both_same=False):
    """Run dog with pty on stdout and/or stderr. Returns (out_bytes, err_bytes, rc, reqs).
    If both_same, stdout and stderr share the same pty (so they interleave into out)."""
    p = nextport()
    box = []
    if respbytes is not None:
        def respfn(req, i):
            r = respbytes(req,i) if callable(respbytes) else respbytes
            if r is None: return None
            if patchid and len(r)>=2: r = req[0:2]+r[2:]
            return r
        target = serve_tcp if tcp else serve_udp
        th = threading.Thread(target=target, args=(p, respfn, box, count), daemon=True)
        th.start()
        time.sleep(0.25)
    args = [DOG] + [a.replace('@PORT@', str(p)) for a in dogargs]
    e = dict(os.environ)
    if env:
        for k,v in env.items():
            if v is None: e.pop(k, None)
            else: e[k]=v

    masters = []
    kw = {}
    if out_tty:
        mo, so = pty.openpty(); masters.append(('out',mo)); kw['stdout']=so
    else:
        kw['stdout']=subprocess.PIPE
    if both_same and out_tty:
        kw['stderr']=so
    elif err_tty:
        me, se = pty.openpty(); masters.append(('err',me)); kw['stderr']=se
    else:
        kw['stderr']=subprocess.PIPE
    kw['stdin']=subprocess.DEVNULL
    proc = subprocess.Popen(args, env=e, **kw)
    # close slave fds in parent
    if out_tty: os.close(so)
    if (not both_same) and err_tty:
        try: os.close(se)
        except Exception: pass
    bufs = {'out':b'','err':b''}
    fds = {m:n for (n,m) in masters}
    open_fds = list(fds)
    deadline = time.time()+timeout
    while open_fds and time.time()<deadline:
        r,_,_ = select.select(open_fds, [], [], 0.2)
        for fd in r:
            try:
                d = os.read(fd, 65536)
            except OSError:
                d = b''
            if not d:
                open_fds.remove(fd); continue
            bufs[fds[fd]] += d
    rc = proc.poll()
    if rc is None:
        try: proc.wait(timeout=3)
        except Exception: proc.kill()
        rc = proc.poll()
    if not out_tty:
        bufs['out'] = proc.stdout.read() if proc.stdout else b''
    if not err_tty and not both_same:
        bufs['err'] = proc.stderr.read() if proc.stderr else b''
    for _,fd in masters:
        try: os.close(fd)
        except Exception: pass
    reqs = [b for (k,b) in box if k=='req']
    return bufs['out'], bufs['err'], rc, reqs
PYEOF
